(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.015+t*0.2)*20 + Math.cos(y*0.02-t*0.15)*15;
  const w1y = Math.cos(y*0.018-t*0.25)*18 + Math.sin(x*0.022+t*0.3)*12;
  const w2x = Math.sin((x+w1x)*0.025-t*0.4)*10 + Math.cos((y+w1y)*0.03+t*0.35)*8;
  const w2y = Math.cos((y+w1y)*0.028+t*0.45)*9 + Math.sin((x+w1x)*0.032-t*0.38)*7;
  const sx = x + w1x + w2x, sy = y + w1y + w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.9],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 1.1],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.8],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 1.0],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 0.95],
    [100+Math.sin(t*1.2)*60, 40+Math.cos(t*0.9)*40, 0.18, 3.2, 0.5],
    [400+Math.cos(t*1.1)*50, 200+Math.sin(t*1.3)*50, 0.2, 2.8, 0.45],
    [200+Math.sin(t*0.8+3)*70, 220+Math.cos(t*1.0+1)*45, 0.15, 3.5, 0.55],
    [300+Math.cos(t*0.7+2)*80, 30+Math.sin(t*1.1+4)*35, 0.16, 3.0, 0.5]
  ];
  let aS = 0, iS = 0, aW = 0, iW = 0;
  for (let j = 0; j < src.length; j++) {
    const [sX, sY, f, sp, wt] = src[j];
    const d = Math.sqrt((sx-sX)**2 + (sy-sY)**2);
    const a = Math.sin(d*f - t*sp);
    const inh = Math.sin(d*f*0.7 + t*sp*0.6 + 1.5);
    if (j < 6) { aS += a*wt; iS += inh*wt; }
    else { aW += a*wt; iW += inh*wt; }
  }
  const act = aS/6, inh = iS/6, fineAct = aW/4, fineInh = iW/4;
  const bg = (Math.sin(sx*0.04+sy*0.025+t*0.8) + Math.sin(sx*0.03-sy*0.04+t*1.1))/2
    + Math.sin((sx+sy)*0.12+t*2.5)*0.2 + Math.sin((sx-sy)*0.1-t*2)*0.2
    + Math.sin(sx*0.08+t*0.6)*Math.cos(sy*0.07-t*0.5)*0.15;
  const dist = Math.sqrt((sx-cx)**2 + (sy-cy)**2);
  const ang = Math.atan2(sy-cy, sx-cx);
  const breath = 1 + Math.sin(t*0.3)*0.2;
  const spiral = (Math.sin(dist*0.05*breath-ang*3-t*1.5)
    + Math.sin(dist*0.04+ang*4-t*1.2)
    + Math.sin(dist*0.06*breath-ang*2-t*0.8)*0.5)*0.35;
  const reaction = Math.tanh((act - inh*0.7 + bg*0.3 + spiral)*2.2);
  const fineReaction = Math.tanh((fineAct - fineInh*0.6 + bg*0.2)*2.5)*0.4;
  const cell = Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)
    + Math.sin((sx+sy)*0.1+t)*0.5
    + Math.sin(sx*0.2-sy*0.18+t*0.7)*0.3)*1.5)*0.3;
  const micro = Math.sin(sx*0.4+t*1.5)*Math.sin(sy*0.35-t*1.2)*0.1;
  const blend = reaction*0.55 + cell*0.2 + fineReaction*0.15 + micro*0.1;
  const v = blend*0.5+0.5;
  const pal = [
    [5,12,52],[12,45,85],[18,90,115],[25,140,130],[60,175,120],
    [140,195,80],[210,190,60],[225,145,55],[210,100,65],[180,60,70],
    [120,35,65],[60,18,55],[20,10,50],[5,12,52]
  ];
  const idx = v*(pal.length-1);
  const i = Math.min(idx|0, pal.length-2);
  const f = idx-i;
  const sf = f*f*(3-2*f);
  const lum = 0.85 + Math.sin(reaction*Math.PI)*0.15 + fineReaction*0.1;
  const edge = Math.abs(reaction)>0.65 ? 1.1 + (Math.abs(reaction)-0.65)*0.5 : 1.0;
  const glow = Math.max(0, 1 - Math.abs(reaction)*1.5)*0.15;
  const r = (pal[i][0]+(pal[i+1][0]-pal[i][0])*sf)*lum*edge + glow*60;
  const g = (pal[i][1]+(pal[i+1][1]-pal[i][1])*sf)*lum*edge + glow*80;
  const b = (pal[i][2]+(pal[i+1][2]-pal[i][2])*sf)*lum*edge + glow*120;
  return [
    Math.min(255, Math.max(0, r))|0,
    Math.min(255, Math.max(0, g))|0,
    Math.min(255, Math.max(0, b))|0
  ];
}
